import { useEffect, useState } from "react";
import DashboardLayout from "../layouts/DashboardLayout";
import Loader from "../components/Loader";
import api from "../services/api";

export default function Campaigns() {
  const [campaigns, setCampaigns] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    api.get("/campaigns")
      .then((res) => setCampaigns(res.data))
      .finally(() => setLoading(false));
  }, []);

  return (
    <DashboardLayout title="Campaigns">
      {loading ? (
        <Loader />
      ) : (
        <div className="campaign-list">
          {campaigns.map((campaign) => {
            const progress = Math.min(100, Math.round((campaign.raisedAmount / campaign.goalAmount) * 100));
            return (
              <section className="card" key={campaign._id}>
                <h3>{campaign.title}</h3>
                <p>{campaign.description}</p>
                <div className="progress"><span style={{ width: `${progress}%` }} /></div>
                <p>Rs {Number(campaign.raisedAmount).toLocaleString("en-IN")} of Rs {Number(campaign.goalAmount).toLocaleString("en-IN")}</p>
              </section>
            );
          })}
        </div>
      )}
    </DashboardLayout>
  );
}
